'use strict';

var index = require('./index-OWCBTetj.js');

const cardLinksCss = () => `.container{display:flex;align-items:center;gap:20px;flex-wrap:wrap;text-decoration:none;color:#1d1d1d;padding:var(--card-links-padding, 0px 24px 24px 24px);padding-top:var(--card-links-padding-top, 0px);word-wrap:break-word;overflow-wrap:anywhere;}.container:hover{cursor:initial}`;

const CardLinks = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
    }
    get el() { return index.getElement(this); }
    render() {
        return (index.h("div", { key: '42815a3602638649749599136a205ec78a4ff1b1', class: "container" }, index.h("slot", { key: 'e946fdd5ab48d1f4581ef69d9f8f5c359c19a845' })));
    }
};
CardLinks.style = cardLinksCss();

exports.ifx_card_links = CardLinks;
